const items = $input.all();
const formData = $('On form submission').first().json;

const today = new Date();
today.setUTCHours(0, 0, 0, 0);

function parseDate(value) {
  if (!value) return null;

  const str = String(value).trim();
  let date;

  if (/^\d{4}-\d{2}-\d{2}$/.test(str)) {
    date = new Date(`${str}T00:00:00Z`);
  } else if (/^\d{2}\/\d{2}\/\d{4}$/.test(str)) {
    const [day, month, year] = str.split('/');
    date = new Date(Date.UTC(Number(year), Number(month) - 1, Number(day)));
  } else {
    return null;
  }

  if (Number.isNaN(date.getTime())) return null;

  // Reject impossible dates
  const parts = str.includes('-')
    ? str.split('-').map(Number)
    : str.split('/').reverse().map(Number);

  const [year, month, day] = parts;

  if (
    date.getUTCFullYear() !== year ||
    date.getUTCMonth() + 1 !== month ||
    date.getUTCDate() !== day
  ) {
    return null;
  }

  return date;
}

return items.map(item => {
  const invoice = item.json;

  const status = String(invoice.payment_status || '')
    .trim()
    .toLowerCase();

  const dueDate = parseDate(invoice.due_date);

  let daysOverdue = 0;
  let urgencyLevel = 'Not overdue';
  let eligible = false;
  let reason = '';

  const paidStatuses = ['paid', 'settled', 'complete', 'completed'];
  const cancelledStatuses = ['cancelled', 'canceled', 'void', 'refunded'];
  const unpaidStatuses = [
    'unpaid',
    'overdue',
    'outstanding',
    'pending',
    'open',
    'partially paid'
  ];

  if (paidStatuses.includes(status)) {
    reason = 'Invoice already paid — no reminder required.';
  } else if (cancelledStatuses.includes(status)) {
    reason = 'Invoice cancelled or refunded — no reminder required.';
  } else if (!dueDate) {
    reason = 'Missing or invalid due date — manual review required.';
  } else if (!unpaidStatuses.includes(status)) {
    reason = 'Unrecognized invoice status — manual review required.';
  } else if (dueDate >= today) {
    reason = 'Invoice is not overdue yet.';
  } else {
    daysOverdue = Math.floor(
      (today.getTime() - dueDate.getTime()) / 86400000
    );

    eligible = true;

    if (daysOverdue <= 7) {
      urgencyLevel = 'Level 1 — Friendly Reminder';
    } else if (daysOverdue <= 15) {
      urgencyLevel = 'Level 2 — Professional Follow-up';
    } else if (daysOverdue <= 30) {
      urgencyLevel = 'Level 3 — Firm Reminder';
    } else {
      urgencyLevel = 'Level 4 — Urgent Payment Notice';
    }

    reason = 'Unpaid invoice past its due date.';
  }

  return {
    json: {
      ...invoice,
      company_name: formData['Company Name'],
      company_email: formData['Company Email'],
      currency: invoice.currency || formData.Currency,
      reminder_language: formData['Reminder Language'],
      payment_terms: formData['Default Payment Terms'] || 'Not specified',
      days_overdue: daysOverdue,
      urgency_level: urgencyLevel,
      eligible_for_reminder: eligible,
      processing_reason: reason
    }
  };
});

